def compute(vars):
    change = vars["v2"] - vars["v1"]
    return {
        "value": change,
        "trace": {
            "2018_charge": vars["v1"],
            "2019_charge": vars["v2"],
            "change": change,
            "output_meta": {
                "currency": "GBP",
                "scale": "million",
                "unit": None
            }
        }
    }
